44	const PROCESSING_FEE = 5;
45	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
46	
47	const BASE_PREMIUMS = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	} as const satisfies Record<string, number>;
55	
56	export type InsurableItemType = keyof typeof BASE_PREMIUMS;
57	
58	const basePremiumForType = (type: string): number =>
59	  BASE_PREMIUMS[type as InsurableItemType];
60	
61	const BLOCK_SIZE = 3;
62	const BLOCK_PREMIUM = 60;
63	
64	const countByType = (items: Item[]): Map<string, number> => {
65	  const counts = new Map<string, number>();
66	  for (const item of items) {
67	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
68	  }
69	  return counts;
70	};
71	
72	// A building block of exactly 3 alike items is offered at a flat base premium.
73	// "Alike" means the same item type — 2 runes + 1 moonstone is not a block.
74	const basePremiumForAlikeItems = (type: string, count: number): number =>
75	  count === BLOCK_SIZE ? BLOCK_PREMIUM : count * basePremiumForType(type);
76	
77	const sumBasePremiums = (items: Item[]): number =>
78	  [...countByType(items)].reduce(
79	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
80	    0,
81	  );
82	
83	// Premiums are rounded up, in the MHPCO's favour; only the final premium is
84	// rounded, intermediate amounts stay fractional.
85	const roundInMHPCOsFavour = Math.ceil;
86	
87	const quotePremium = (items: Item[]): number => {
88	  const basePremium = sumBasePremiums(items);
89	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
90	  return roundInMHPCOsFavour(
91	    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
92	  );
93	};
94	
95	const runStep = (step: Step): QuoteResult | ClaimResult => {
96	  switch (step.op) {
97	    case "quote":
98	      return { premium: quotePremium(step.items) };
99	    case "claim":
100	      throw new Error("claim steps are not supported yet");
101	  }
102	};
103	
104	export const runScenario = (scenario: Scenario): ScenarioResults => ({
105	  results: scenario.steps.map(runStep),
106	});
